<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useServiceContext} from '@/composables/useServiceContext'
import {isCities,isSearch,kinds,publicLink,query,type Cities,type Json,type PublicKind} from '@/api/modules/clientServices'
import {directoryCity,setDirectoryCity} from '@/business/directoryCity'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
import StockPublicMedia from '@/components/business/StockPublicMedia.vue'
const route=useRoute(),ui=useServiceContext(()=>null),{error,notice}=ui
const cities=ref<Cities|null>(null),kind=ref<PublicKind>('ARTIST'),city=ref(directoryCity.value),term=ref(''),items=ref<Json[]>([]),cursor=ref<string|number|null>(null),loading=ref(false),loaded=ref(false),localCity=ref(false)
let serial=0,initialized=false
const empty=computed(()=>loaded.value&&!items.value.length&&!cursor.value&&!error.value)
const title=(r:Json)=>String(r.display_name||r.title||r.data?.title||r.notice?.title||r.data?.notice?.title||kinds[kind.value])
const text=(r:Json)=>String(r.introduction||r.description||r.data?.description||r.notice?.description||r.data?.notice?.description||r.service_area||'')
function clear(){ui.cancelReads();error.value=null;serial++;items.value=[];cursor.value=null;loaded.value=false;loading.value=false}
async function load(more=false){error.value=null;if(loading.value||more&&!cursor.value)return;const turn=++serial,previous=more?cursor.value:null,chosen=kind.value;if(!more){items.value=[];cursor.value=null;loaded.value=false}loading.value=true;const result=await ui.read('/discovery/search'+query({kind:chosen,city:city.value.trim(),q:term.value.trim(),cursor:previous,limit:20}),isSearch);if(turn!==serial)return;loading.value=false;if(!result)return;if(result.kind!==chosen||previous!==null&&result.next_cursor===previous){ui.fail('查询结果或分页位置不一致，请重新查找。');return}items.value=more?[...new Map([...items.value,...result.items].map(r=>[r.listing_id||r.id,r])).values()]:result.items;cursor.value=result.next_cursor;loaded.value=true}
async function ready(){initialized=true;const s=ui.signature.value,c=await ui.read('/discovery/cities',isCities);if(s!==ui.signature.value)return;cities.value=c;await load()}
watch(()=>[kind.value,city.value,term.value],clear,{flush:'sync'})
watch(ui.revision,()=>{clear();cities.value=null;if(initialized&&ui.ready.value)void ready()},{flush:'sync'})
watch(directoryCity,v=>{if(!localCity.value)city.value=v})
function defaultCity(){setDirectoryCity(city.value);localCity.value=false;notice.value=city.value?'已设为其他目录的默认城市。':'已清除目录默认城市。'}
</script>
<template><ServiceWorkspace title="查找公开内容" intro="按城市和关键词查找当前可公开的艺人、现成影片、试镜与通告。" account-only :error="error" :notice="notice" @ready="ready"><div class="service-tabs"><RouterLink to="/directory/organizations">公开机构</RouterLink><RouterLink to="/directory/featured">精选艺人</RouterLink><RouterLink to="/me/collections/favorites">我的收藏</RouterLink></div><form class="supply-card" @submit.prevent="load()"><div class="service-form"><label>内容类别<select v-model="kind"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label><label>城市<input v-model="city" list="discovery-cities" placeholder="全部城市，或输入城市名称" maxlength="100" @input="localCity=true"><datalist id="discovery-cities"><option v-for="item in cities?.items" :key="item.code" :value="item.name"/></datalist></label><label class="wide">关键词<input v-model="term" type="search" maxlength="200" placeholder="公开名称、介绍或标签"></label></div><p class="service-muted">快捷城市来自服务器；也可输入其他城市名称精确查找。结果按记录顺序展示。</p><div class="service-actions"><button class="primary" :disabled="loading">查找</button><button type="button" class="outline" @click="defaultCity">将本页城市用于其他目录</button><button v-if="localCity" type="button" class="outline" @click="localCity=false;city=directoryCity">使用目录默认城市</button></div></form><section class="supply-card"><p v-if="loading" role="status">正在查找…</p><div class="service-grid"><article v-for="item in items" :key="item.listing_id||item.id" class="service-result"><StockPublicMedia v-if="kind==='STOCK'" :record="item" :name="title(item)" :scope="route.fullPath+kind+city+term"/><p class="service-muted">{{kinds[kind]}} · {{item.city||item.data?.city||item.notice?.city||''}}</p><h2>{{title(item)}}</h2><p class="service-text">{{text(item)}}</p><p v-if="kind==='AUDITION'">{{item.unit_minor===null?'价格未公开':Number.isSafeInteger(item.unit_minor)?'¥'+(item.unit_minor/100).toFixed(2):'进入方案查看具体费用'}}</p><RouterLink class="button-link outline" :to="publicLink(kind,item.listing_id||item.id)">查看当前详情</RouterLink></article></div><p v-if="empty" class="supply-empty">没有找到当前可公开的结果。</p><p v-if="!items.length&&cursor" role="status">本页没有匹配内容，后面还有待查询的记录。</p><button v-if="cursor" class="outline" :disabled="loading" @click="load(true)">{{items.length?'加载更多':'继续查找'}}</button><button v-if="error" class="outline" :disabled="loading" @click="load()">保留条件重新查找</button></section></ServiceWorkspace></template>
